#!/usr/bin/env bash\nset -e\n\n# Mock rationale: Verify that required Terraform files exist and contain expected resources.\n\nMODULE_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")/../..\" && pwd)\"\n\n# Check main.tf contains aws_s3_bucket resource\nif ! grep -q 'resource "aws_s3_bucket" "safehouse"' \"$MODULE_DIR/src/main.tf\"; then\n  echo \"FAIL: aws_s3_bucket resource not found\"\n  exit 1\nfi\n\n# Check variables.tf defines bucket_name\nif ! grep -q 'variable "bucket_name"' \"$MODULE_DIR/src/variables.tf\"; then\n  echo \"FAIL: bucket_name variable missing\"\n  exit 1\nfi\n\n# Run terraform validate (offline, no provider download)\npushd \"$MODULE_DIR/src\" > /dev/null\nterraform init -backend=false -get=false > /dev/null 2>&1 || {\n  echo \"FAIL: terraform init failed (expected offline mock)\"\n  exit 1\n}\nterraform validate -no-color > /dev/null 2>&1 || {\n  echo \"FAIL: terraform validate failed\"\n  exit 1\n}\npopd > /dev/null\n\necho \"PASS: All checks passed\"
